// DataBrokerServer is the server API for DataBroker service.
// All implementations should embed UnimplementedDataBrokerServer
// for forward compatibility.
//
// DataBroker is the UDB-owned wire protocol. Project protos are parsed only as
// schema input; they do not need to contain or import this service contract.
type DataBrokerServer interface {
	// ── Relational ─────────────────────────────────────────────────────────────
	Select(context.Context, *v1.SelectRequest) (*v1.RecordSet, error)
	BatchSelect(grpc.BidiStreamingServer[v1.SelectRequest, v1.RecordSet]) error
	Upsert(context.Context, *v1.UpsertRequest) (*v1.MutationResponse, error)
	BatchUpsert(grpc.BidiStreamingServer[v1.UpsertRequest, v1.MutationResponse]) error
	// Delete rows without raw SQL.
	Delete(context.Context, *v1.DeleteRequest) (*v1.MutationResponse, error)
	// ── Vector ──────────────────────────────────────────────────────────────────
	VectorSearch(context.Context, *v1.VectorSearchRequest) (*v1.VectorSet, error)
	VectorHybridSearch(context.Context, *v1.VectorHybridSearchRequest) (*v1.VectorSet, error)
	VectorUpsert(context.Context, *v1.VectorUpsertRequest) (*v1.MutationResponse, error)
	VectorBatchUpsert(grpc.BidiStreamingServer[v1.VectorUpsertRequest, v1.MutationResponse]) error
	// ── Blob ───────────────────────────────────────────────────────────────────
	PutObject(grpc.ClientStreamingServer[v1.Chunk, v1.MutationResponse]) error
	GetObject(*v1.ObjectRequest, grpc.ServerStreamingServer[v1.Chunk]) error
	GeneratePresignedUrl(context.Context, *v1.UrlRequest) (*v1.UrlResponse, error)
	InitiateMultipartUpload(context.Context, *v1.MultipartUploadRequest) (*v1.MultipartUploadResponse, error)
	// ── Cache / KV ─────────────────────────────────────────────────────────────
	CacheGet(context.Context, *v1.CacheGetRequest) (*v1.CacheGetResponse, error)
	CacheSet(context.Context, *v1.CacheSetRequest) (*v1.MutationResponse, error)
	CacheDelete(context.Context, *v1.CacheDeleteRequest) (*v1.MutationResponse, error)
	CacheScan(context.Context, *v1.CacheScanRequest) (*v1.CacheScanResponse, error)
	// ── Document / Graph / Time-Series / Analytical Stores ────────────────────
	DocumentGet(context.Context, *v1.DocumentGetRequest) (*v1.DocumentSet, error)
	DocumentFind(context.Context, *v1.DocumentFindRequest) (*v1.DocumentSet, error)
	DocumentUpsert(context.Context, *v1.DocumentUpsertRequest) (*v1.MutationResponse, error)
	DocumentDelete(context.Context, *v1.DocumentDeleteRequest) (*v1.MutationResponse, error)
	GraphQuery(context.Context, *v1.GraphQueryRequest) (*v1.GraphResultSet, error)
	GraphMutate(context.Context, *v1.GraphMutationRequest) (*v1.MutationResponse, error)
	TimeSeriesWrite(context.Context, *v1.TimeSeriesWriteRequest) (*v1.MutationResponse, error)
	TimeSeriesQuery(context.Context, *v1.TimeSeriesQueryRequest) (*v1.TimeSeriesQueryResponse, error)
	AnalyticalQuery(context.Context, *v1.AnalyticalQueryRequest) (*v1.AnalyticalQueryResponse, error)
	// ── Tx / CDC ───────────────────────────────────────────────────────────────
	BeginTx(grpc.BidiStreamingServer[v1.Mutation, v1.TxStatus]) error
	PublishCDC(*v1.CDCSubscriptionRequest, grpc.ServerStreamingServer[v11.CDCEnvelope]) error
	CreateMaterializedView(context.Context, *v1.ViewDefinition) (*v1.MutationResponse, error)
	// ── First-Class Event API ─────────────────────────────────────────────────
	EnqueueOutboxEvent(context.Context, *v1.EnqueueOutboxEventRequest) (*v1.EnqueueOutboxEventResponse, error)
	// Generic resource administration.
	// Dispatch a lifecycle operation to any configured backend executor.
	// Requires scope: udb:dispatch
	GenericDispatch(context.Context, *v1.GenericDispatchRequest) (*v1.GenericDispatchResponse, error)
	// Ensure a named resource exists on the target backend.
	// Requires scope: udb:admin
	EnsureResource(context.Context, *v1.ResourceAdminRequest) (*v1.MutationResponse, error)
	// Drop a named resource on the target backend.
	// Requires scope: udb:admin
	DropResource(context.Context, *v1.ResourceAdminRequest) (*v1.MutationResponse, error)
	// List all resources managed by the target backend.
	// Requires scope: udb:admin
	ListResources(context.Context, *v1.ResourceAdminRequest) (*v1.ResourceListResponse, error)
	// Catalog administration.
	// Stage a new catalog manifest version (validate + store as STAGED).
	// Requires scope: udb:admin
	StageCatalog(context.Context, *v1.StageCatalogRequest) (*v1.CatalogVersionResponse, error)
	// Activate a STAGED catalog version.
	// Requires scope: udb:admin
	ActivateCatalog(context.Context, *v1.CatalogVersionRequest) (*v1.CatalogVersionResponse, error)
	// Roll back to the previous ACTIVE catalog version.
	// Requires scope: udb:admin
	RollbackCatalog(context.Context, *v1.CatalogVersionRequest) (*v1.CatalogVersionResponse, error)
	// Validate a catalog manifest JSON without storing it.
	// Requires scope: udb:admin
	ValidateCatalog(context.Context, *v1.StageCatalogRequest) (*v1.CatalogValidationResponse, error)
	// Return the list of known catalog versions.
	// Requires scope: udb:admin
	GetCatalogVersions(context.Context, *v1.CatalogManifestRequest) (*v1.CatalogVersionListResponse, error)
	// Return one catalog version by catalog_id/version, or active version when empty.
	// Requires scope: udb:admin
	GetCatalogVersion(context.Context, *v1.CatalogVersionRequest) (*v1.CatalogVersionResponse, error)
	// Migration planning and apply.
	// Plan a migration against the active catalog without executing it.
	// Requires scope: udb:admin
	PlanMigration(context.Context, *v1.MigrationPlanRequest) (*v1.MigrationPlanResponse, error)
	// Apply a previously planned (and optionally approved) migration.
	// Requires scope: udb:admin
	ApplyMigration(context.Context, *v1.MigrationApplyRequest) (*v1.MigrationStatusResponse, error)
	// Return the status of a migration run.
	// Requires scope: udb:admin
	GetMigrationStatus(context.Context, *v1.MigrationRunRequest) (*v1.MigrationStatusResponse, error)
	// Return migration runs for an admin console page.
	// Requires scope: udb:admin, udb:admin:viewer, or legacy udb:portal:viewer.
	ListMigrationRuns(context.Context, *v1.MigrationRunListRequest) (*v1.MigrationRunListResponse, error)
	// Approve a migration plan that requires review.
	// Requires scope: udb:admin
	ApproveMigrationPlan(context.Context, *v1.MigrationRunRequest) (*v1.MigrationStatusResponse, error)
	// DLQ management.
	ListDlqEvents(context.Context, *v1.DlqListRequest) (*v1.DlqListResponse, error)
	GetDlqEvent(context.Context, *v1.DlqEventRequest) (*v1.DlqEventResponse, error)
	ReplayDlqEvent(context.Context, *v1.DlqActionRequest) (*v1.MutationResponse, error)
	DismissDlqEvent(context.Context, *v1.DlqActionRequest) (*v1.MutationResponse, error)
	QuarantineDlqEvent(context.Context, *v1.DlqActionRequest) (*v1.MutationResponse, error)
	// CDC control plane.
	GetCdcStatus(context.Context, *v1.CdcControlRequest) (*v1.CdcStatusResponse, error)
	PauseCdc(context.Context, *v1.CdcControlRequest) (*v1.CdcStatusResponse, error)
	ResumeCdc(context.Context, *v1.CdcControlRequest) (*v1.CdcStatusResponse, error)
	StepDownCdcLeader(context.Context, *v1.CdcControlRequest) (*v1.CdcStatusResponse, error)
	PreviewCdcRedaction(context.Context, *v1.CdcRedactionPreviewRequest) (*v1.CdcRedactionPreviewResponse, error)
	// Saga administration.
	ListSagas(context.Context, *v1.SagaListRequest) (*v1.SagaListResponse, error)
	GetSaga(context.Context, *v1.SagaRequest) (*v1.SagaResponse, error)
	RetrySagaCompensation(context.Context, *v1.SagaRequest) (*v1.SagaResponse, error)
	MarkSagaReviewed(context.Context, *v1.SagaRequest) (*v1.SagaResponse, error)
	// Policy administration.
	ListPolicies(context.Context, *v1.PolicyListRequest) (*v1.PolicyListResponse, error)
	PutPolicy(context.Context, *v1.PutPolicyRequest) (*v1.MutationResponse, error)
	DeletePolicy(context.Context, *v1.PolicyRequest) (*v1.MutationResponse, error)
	ReloadPolicies(context.Context, *v1.CapabilitiesRequest) (*v1.MutationResponse, error)
	LintPolicies(context.Context, *v1.CapabilitiesRequest) (*v1.PolicyLintResponse, error)
	// ── Admin API ─────────────────────────────────────────────────────────────
	GetCapabilities(context.Context, *v1.CapabilitiesRequest) (*v1.CapabilitiesResponse, error)
	GetCatalogManifest(context.Context, *v1.CatalogManifestRequest) (*v1.CatalogManifestResponse, error)
	// Runtime schema lookup for SDK/data operation compatibility negotiation.
	LookupMessageSchema(context.Context, *v1.MessageSchemaLookupRequest) (*v1.MessageSchemaLookupResponse, error)
	ListMessageSchemas(context.Context, *v1.MessageSchemaListRequest) (*v1.MessageSchemaListResponse, error)
	GetHealthReport(context.Context, *v1.HealthReportRequest) (*v1.HealthReportResponse, error)
	// Multi-project registry.
	// Ensure a project namespace exists (idempotent).
	// Requires scope: udb:admin
	EnsureProject(context.Context, *v1.EnsureProjectRequest) (*v1.MutationResponse, error)
	// List all registered project namespaces.
	// Requires scope: udb:admin
	ListProjects(context.Context, *v1.ProjectListRequest) (*v1.ProjectListResponse, error)
	// ── Unified Admin Surface ────────────────────────────────────────────────
	// Returns a single snapshot covering catalog, CDC, saga, backend, and policy
	// state for the admin console. Requires scope: udb:admin.
	GetAdminSummary(context.Context, *v1.AdminSummaryRequest) (*v1.AdminSummaryResponse, error)
	// Paginated admin audit log view for the admin console.
	// Requires scope: udb:admin, udb:admin:viewer, or legacy udb:portal:viewer.
	ListAdminAuditLogs(context.Context, *v1.AdminAuditLogRequest) (*v1.AdminAuditLogResponse, error)
	// Verifies the admin audit log hash chain and reports the first broken link.
	// Requires scope: udb:admin, udb:admin:viewer, or legacy udb:portal:viewer.
	VerifyAdminAuditLog(context.Context, *v1.AdminAuditVerifyRequest) (*v1.AdminAuditVerifyResponse, error)
}

